# A summary of each column, with the custom function
# and a threshold of 20, written in parentheses
exibble_j = exibble_a.grand_summary_rows(
    fns={
        "high": pl.col("num", "currency").map_batches(
            lambda s: pl.Series([agg_highest_two_above_value(s.to_list(), 20)]),
            return_dtype=pl.String,
            returns_scalar=True,
        )
    },
    fmt=lambda xs: [f"({x})" for x in xs],
)

exibble_j
